  "sql": "WITH _base AS (\n  SELECT\n    customers.tier AS \"customers.tier\",\n    COUNT(*) AS \"customers.customers\"\n  FROM customers AS customers\n  GROUP BY\n    customers.tier\n), _cm_customers__orders__amount_sum AS (\n  SELECT\n    customers.tier AS \"orders.customers.tier\",\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.amount_sum\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  GROUP BY\n    customers.tier\n)\nSELECT\n  _base.\"customers.tier\",\n  _base.\"customers.customers\",\n  _cm_customers__orders__amount_sum.\"orders.amount_sum\" AS \"customers.revenue\"\nFROM _base\nLEFT JOIN _cm_customers__orders__amount_sum\n  ON _base.\"customers.tier\" IS NOT DISTINCT FROM _cm_customers__orders__amount_sum.\"orders.customers.tier\"\nORDER BY\n  _base.\"customers.tier\" ASC\nLIMIT 101"
